#!/usr/bin/env python3 -I
"""#1305: writes src/elevationgrid.js (the ground grid `g` of data/elevation.json as a synchronous ES module, so every
page and test that builds the terrain has it without a fetch). Run from the repo root after tools/elevation_grid.py."""
import json
d = json.load(open('data/elevation.json'))
rows = ',\n'.join(' [' + ','.join(str(v) for v in r) + ']' for r in d['g'])
open('src/elevationgrid.js', 'w').write(
    '// GENERATED by tools/elevation_js.py from data/elevation.json (#1288, #1305): do not edit. Copernicus GLO-30, "Contains modified Copernicus data".\n'
    '// `g` = bare-earth estimate in decimetres relative to the L1007 courtyard, rows = z (from z0), columns = x (from x0), every `step` m.\n'
    'export const ELEVATION_GRID = { x0: %d, z0: %d, step: %d, cols: %d, rows: %d, g: [\n%s\n] };\n'
    % (d['x0'], d['z0'], d['step'], d['cols'], d['rowsN'], rows))
